def save_to_csv(matches, year):
    with open(f'data/{year}.csv', 'w', newline='', encoding='utf-8') as f:
        writer = csv.DictWriter(f, fieldnames=['date', 'competition', 'home_team', 'away_team', 'home_score', 'away_score', 'result'])
        writer.writeheader()
        writer.writerows(matches)
    print(f'Saved {len(matches)} matches to data/{year}.csv')

def save_to_json(matches, year):
    with open(f'data/{year}_raw.json', 'w', encoding='utf-8') as f:
        json.dump(matches, f, indent=2, ensure_ascii=False)
    print(f'Saved {len(matches)} matches to data/{year}_raw.json')

if __name__ == '__main__':
    import os
    os.makedirs('data', exist_ok=True)
    
    years_data = [
        (2019, matches_2019),
        (2020, matches_2020),
        (2021, matches_2021),
        (2022, matches_2022),
        (2023, matches_2023),
        (2024, matches_2024),
        (2025, matches_2025),
        (2026, matches_2026),
    ]
    
    for year, matches in years_data:
        save_to_csv(matches, year)
        save_to_json(matches, year)
    
    total = sum(len(m) for _, m in years_data)
    print(f'\nTotal matches extracted: {total}')
